from ortools.sat.python import cp_model
import itertools
import json

def main():
    protocols = ['Alpha', 'Beta', 'Gamma', 'Delta', 'Epsilon', 'Zeta', 'Eta', 'Theta', 'Iota', 'Kappa']
    instruments = list(range(1, 11))
    phases = list(range(1, 11))

    sequence = {
        'Alpha': [3, 4, 10, 2, 9, 1, 5, 8, 7, 6],
        'Beta': [10, 6, 5, 2, 4, 8, 7, 3, 1, 9],
        'Gamma': [5, 3, 9, 1, 10, 8, 2, 7, 6, 4],
        'Delta': [7, 6, 5, 9, 1, 8, 10, 4, 3, 2],
        'Epsilon': [5, 10, 8, 1, 3, 4, 7, 9, 6, 2],
        'Zeta': [1, 4, 7, 8, 2, 10, 9, 5, 3, 6],
        'Eta': [2, 8, 3, 6, 4, 5, 10, 7, 9, 1],
        'Theta': [4, 8, 2, 3, 5, 10, 1, 7, 9, 6],
        'Iota': [8, 7, 3, 2, 4, 1, 9, 5, 10, 6],
        'Kappa': [8, 10, 5, 9, 7, 4, 6, 1, 2, 3]
    }

    duration = {
        'Alpha': [40, 36, 19, 21, 8, 19, 40, 20, 43, 2],
        'Beta': [19, 32, 46, 9, 44, 27, 23, 3, 30, 28],
        'Gamma': [43, 18, 48, 12, 16, 27, 35, 12, 10, 26],
        'Delta': [13, 4, 26, 15, 35, 1, 28, 47, 27, 29],
        'Epsilon': [23, 47, 44, 3, 47, 2, 34, 9, 16, 49],
        'Zeta': [34, 41, 25, 33, 41, 9, 30, 12, 9, 10],
        'Eta': [11, 12, 47, 46, 25, 33, 23, 46, 38, 41],
        'Theta': [24, 18, 1, 37, 50, 31, 40, 29, 23, 40],
        'Iota': [31, 31, 25, 18, 30, 38, 20, 23, 49, 42],
        'Kappa': [43, 35, 16, 25, 24, 38, 42, 18, 40, 34]
    }

    model = cp_model.CpModel()

    total_duration = sum(sum(duration[p]) for p in protocols)
    horizon = total_duration

    start_time = {}
    for p in protocols:
        for j in phases:
            start_time[(p, j)] = model.NewIntVar(0, horizon, f'start_{p}_{j}')

    makespan = model.NewIntVar(0, horizon, 'makespan')

    for p in protocols:
        for j in range(1, 10):
            model.Add(start_time[(p, j+1)] >= start_time[(p, j)] + duration[p][j-1])

    operations_by_instrument = {}
    for p in protocols:
        for j in phases:
            instr = sequence[p][j-1]
            if instr not in operations_by_instrument:
                operations_by_instrument[instr] = []
            operations_by_instrument[instr].append((p, j))

    for instr, operations in operations_by_instrument.items():
        for (p1, j1), (p2, j2) in itertools.combinations(operations, 2):
            precedes = model.NewBoolVar(f'precedes_{p1}_{j1}_{p2}_{j2}')

            model.Add(start_time[(p1, j1)] + duration[p1][j1-1] <= start_time[(p2, j2)]).OnlyEnforceIf(precedes)

            model.Add(start_time[(p2, j2)] + duration[p2][j2-1] <= start_time[(p1, j1)]).OnlyEnforceIf(precedes.Not())

    for p in protocols:
        model.Add(makespan >= start_time[(p, 10)] + duration[p][9])

    model.Minimize(makespan)

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 300.0
    solver.parameters.num_search_workers = 8

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        phase_initiation_times = []
        for p in protocols:
            protocol_times = []
            for j in phases:
                protocol_times.append(solver.Value(start_time[(p, j)]))
            phase_initiation_times.append(protocol_times)
    else:
        phase_initiation_times = []
        solver.Value(makespan)

    print(json.dumps({
        "phase_initiation_times": phase_initiation_times,
        "experimental_completion_duration": solver.Value(makespan) if status in (cp_model.OPTIMAL, cp_model.FEASIBLE) else -1
    }))

if __name__ == '__main__':
    main()
